<?php require_once __DIR__.'/../config/config.php';require_admin();if(isset($_GET['delete'])){ $did=(int)$_GET['delete']; $pdo->prepare('DELETE FROM students WHERE id=?')->execute([$did]); header('Location:index.php'); exit; }
$q=trim($_GET['q']??'');$sql='SELECT * FROM students';$args=[];if($q){$sql.=' WHERE first_name LIKE ? OR father_name LIKE ? OR guardian_phone LIKE ? OR student_code LIKE ? OR course_number LIKE ?';$x="%$q%";$args=[$x,$x,$x,$x,$x];}$sql.=' ORDER BY id DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();require '../partials/header.php';?><div class="panel"><div class="section-title"><div><h2>دانش‌آموزان</h2><span class="muted">جستجو بر اساس اسم دانش‌آموز، اسم پدر و شماره ولی دانش‌آموز</span></div><a class="btn" href="add.php">➕ ثبت دانش‌آموز</a></div><form class="searchbar"><input name="q" value="<?=h($q)?>" placeholder="مثلاً نام یا شماره ولی دانش‌آموز..."><button>جستجو</button></form><div class="student-table-box"><div class="table-scroll student-table-scroll"><table><tr><th>عکس</th><th>شماره دانشجویی</th><th>اسم دانش‌آموز</th><th>نام پدر</th><th>نوع صنف</th><th>درجه</th><th>تایم</th><th>شماره ولی دانش‌آموز</th><th>آدرس کورس</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><?php if($r['photo']&&is_file('../uploads/'.$r['photo'])):?><img class="thumb" src="../uploads/<?=h($r['photo'])?>"><?php else:?><div class="thumb" style="display:grid;place-items:center">—</div><?php endif;?></td><td><?=h($r['student_code'])?></td><td><?=h($r['first_name'])?></td><td><?=h($r['father_name'])?></td><td><?=h($r['course_type'])?></td><td><?=h($r['class_level'])?></td><td><?=h($r['study_time'])?></td><td><?=h($r['guardian_phone'])?></td><td class="course-address-cell"><?=h(course_address())?></td><td><a class="btn secondary" href="edit.php?id=<?=$r['id']?>">ویرایش</a> <a class="btn" href="../cards/student.php?id=<?=$r['id']?>">کارت</a> <a class="btn danger" href="?delete=<?=$r['id']?>" onclick="return confirm('این دانش‌آموز حذف شود؟')">🗑 حذف</a></td></tr><?php endforeach;?></table><?php if(!$rows):?><p class="muted">نتیجه‌ای پیدا نشد.</p><?php endif;?></div><?php require '../partials/footer.php';?>
